class PythonAstBoundaryError(Exception):
    """sourceを構文として解析できない。判断できないので続行しない。"""

    def __init__(self, code, detail=None):
        super().__init__(f"{code}: {detail}" if detail else code)
        self.code = code
        self.detail = detail

