class TaskPythonCacheError(Exception):
    """task専用cacheを安全に扱えない。判断できない入力はここで止める。"""

    def __init__(self, code, detail=None):
        super().__init__(f"{code}: {detail}" if detail else code)
        self.code = code
        self.detail = detail
